import "core-js/modules/es.array.push.js";
/* eslint-disable */
import { get_ai_api_settings } from "@/graphql/queries.js";
import { gpt_ai_settings } from "@/graphql/mutations.js";
import { openai_api_key_verification } from "@/graphql/mutations.js";
import SnackBar from "@/components/SnackBar.vue";
import { API, graphqlOperation } from "aws-amplify";
export default {
  components: {
    SnackBar
  },
  data() {
    return {
      newarray: [],
      newarray2: [],
      aiSelection: false,
      aiSelection2: false,
      maxLength: 3,
      check: false,
      show1: false,
      openAPIKey: "",
      loading: false,
      SnackBarComponent: {},
      getResponse: "",
      bardAPiKey: "",
      openAPIKey2: "",
      displaystatus: ""
    };
  },
  watch: {
    openAPIKey(val) {
      if (val == "") {
        this.displaystatus = "";
      }
    }
  },
  async created() {
    await this.get_api();
  },
  methods: {
    // truncateddText() {
    //   this.openAPIKey =
    //     this.openAPIKey.substring(0, 3) +
    //     "*".repeat(this.openAPIKey.length - 3);
    // },
    async get_api() {
      var data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(get_ai_api_settings, {
          input: {
            organization_id: data.organization.organization_id
          }
        }));
        let response = JSON.parse(result.data.get_ai_api_settings).items[0].ai_types;
        let id_type = JSON.parse(result.data.get_ai_api_settings).items[0].setting_id;
        this.displaystatus = response[0].is_verified == true ? "SUCCESS" : "";
        this.openAPIKey = response[0].organization_ai_apkey;
        this.getResponse = id_type;
      } catch (error) {
        this.loading = false;
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: error.errors[0].message,
          timeout: 5000,
          Top: true
        };
      }
    },
    validate_data() {
      if (this.openAPIKey != "" && this.displaystatus == "SUCCESS") {
        this.create_api();
      } else {
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: "Enter Valid API Key!!",
          timeout: 5000,
          Top: true
        };
      }
    },
    async create_api() {
      this.newarray = [];
      this.loading = true;
      this.newarray.push({
        organization_ai_type: "OPENAI",
        organization_ai_apkey: this.openAPIKey,
        is_verified: this.displaystatus == "SUCCESS" ? true : false
      });
      var data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(gpt_ai_settings, {
          input: {
            organization_id: data.organization.organization_id,
            setting_id: this.getResponse,
            ai_types: this.newarray
          }
        }));
        var response = JSON.parse(result.data.gpt_ai_settings);
        this.loading = false;
        if (response.Status == "SUCCESS") {
          this.SnackBarComponent = {
            SnackbarVmodel: true,
            SnackbarColor: "green",
            SnackbarText: response.Message,
            timeout: 5000,
            Top: true
          };
          this.get_api();
        } else {
          this.SnackBarComponent = {
            SnackbarVmodel: true,
            SnackbarColor: "red",
            SnackbarText: response.Message,
            timeout: 5000,
            Top: true
          };
        }
      } catch (error) {
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: error.errors[0].message,
          timeout: 5000,
          Top: true
        };
        this.loading = false;
      }
    },
    async verifyapi() {
      var data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(openai_api_key_verification, {
          input: {
            customer_api_key: this.openAPIKey
          }
        }));
        var response = JSON.parse(result.data.openai_api_key_verification);
        this.displaystatus = response.Status;
        if (this.displaystatus == "SUCCESS") {
          // this.check = true;
          // this.truncatedText();
        }
        if (response.Status == "ERROR") {
          this.SnackBarComponent = {
            SnackbarVmodel: true,
            SnackbarColor: "red",
            SnackbarText: response.Message,
            timeout: 5000,
            Top: true
          };
        }
      } catch (error) {
        this.tableLoading = false;
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: error.errors[0].message,
          timeout: 5000,
          Top: true
        };
      }
    }
  }
};
